/*
 * FileManager - FatFS filesystem adapter
 *
 * Implements the FM_FSOps function table on top of FatFS (ff.h).  The
 * FatFS library itself is provided by the application (e.g. generated by
 * STM32CubeMX); this file only contains the bridge code.
 */

#include "fm_fatfs.h"

#if FM_USE_FATFS

#include "fm_internal.h"
#include "ff.h"

#include <string.h>
#include <stddef.h>
#include <stdint.h>

#if FM_FATFS_PROVIDE_DISKIO
#include "diskio.h"
#include "fm_cache.h"
#include "fm_sd_bounce.h"
#endif

/* ------------------------------------------------------------------ */
/* FatFS Version Compatibility Macros                                 */
/* ------------------------------------------------------------------ */
#ifndef FF_MAX_SS
#if defined(_MAX_SS)
#define FF_MAX_SS _MAX_SS
#elif defined(FF_MIN_SS)
#define FF_MAX_SS FF_MIN_SS
#else
#define FF_MAX_SS 512
#endif
#endif

#ifndef FF_VOLUMES
#if defined(_VOLUMES)
#define FF_VOLUMES _VOLUMES
#else
#define FF_VOLUMES 1
#endif
#endif

#ifndef LBA_t
typedef DWORD LBA_t;
#endif

/* ------------------------------------------------------------------ */
/* Context and handles                                                 */
/* ------------------------------------------------------------------ */
#if (defined(FF_FS_TINY) && FF_FS_TINY) || (defined(_FS_TINY) && _FS_TINY)
#define FM_FATFS_FATFS_WIN_OFF 0u
#define FM_FATFS_FIL_WIN_OFF 0u
#elif defined(FF_MOCK_H)
/* هاست-با اسموش ff.h: ساختارهای سبک mock عضو win/buf ندارند؛ هم‌ترازی
 * فقط روی هدف واقعی معنا دارد. */
#define FM_FATFS_FATFS_WIN_OFF 0u
#define FM_FATFS_FIL_WIN_OFF 0u
#else
#define FM_FATFS_FATFS_WIN_OFF offsetof(FATFS, win)
#define FM_FATFS_FIL_WIN_OFF offsetof(FIL, buf)
#endif

static void *fm_place_aligned(uint8_t *store, size_t store_len,
                              size_t obj_len, size_t member_off)
{
    uintptr_t base = (uintptr_t)store;
    unsigned mis = (unsigned)((base + member_off) & 31u);
    unsigned add = (mis == 0u) ? 0u : (32u - mis);

    if ((add + obj_len) > store_len)
    {
        return store;
    }
    return store + add;
}

typedef struct
{
    uint8_t fatfs_store[sizeof(FATFS) + 32u];
    FATFS  *fatfs;
    uint8_t pdrv;
    FM_Bool mounted;
    /* Who has this slot: set by FatFS_Init(), cleared by an unmount and
     * by a mount that failed.  `last` stays behind then, with `pdrv`:
     * it is what lets the same FM_FS mount again without a new
     * FatFS_Init(), and what refuses any other one. */
    FM_FS  *owner;
    FM_FS  *last;

    uint8_t file_store[FM_MAX_OPEN_FILES][sizeof(FIL) + 32u];
    FIL    *files[FM_MAX_OPEN_FILES];
    uint8_t file_used[FM_MAX_OPEN_FILES];

    DIR     dirs[FM_MAX_OPEN_DIRS];
    uint8_t dir_used[FM_MAX_OPEN_DIRS];

#if !FM_USE_THREADS
    /* Scratch buffer used to build FatFS drive-qualified paths for file
     * opens without burning FM_PATH_MAX bytes of stack at the deepest
     * call chain (File_* -> file_open_internal -> f_open).  Only safe in
     * single-threaded builds; threaded builds keep a stack buffer. */
    char    open_path[FM_PATH_MAX];
#endif
} FatFS_Ctx;

typedef struct
{
    uint16_t index;
    uint8_t  used;
} FatFSFileHandle;

typedef struct
{
    uint16_t index;
    uint8_t  used;
} FatFSDirHandle;

static FatFS_Ctx g_fatfs[FM_MAX_FS];

#if FM_FATFS_PROVIDE_DISKIO
static FM_Storage *g_fatfs_storage[FF_VOLUMES];
#endif

static FatFS_Ctx *fatfs_ctx(FM_FS *fs)
{
    return (FatFS_Ctx *)fs->user;
}

/* Everything back to its start, except who the slot is for. */
static void fatfs_ctx_reset(FatFS_Ctx *ctx)
{
    FM_FS *owner = ctx->owner;
    FM_FS *last = ctx->last;
    uint8_t pdrv = ctx->pdrv;
    uint32_t i;

    memset(ctx, 0, sizeof(*ctx));
    ctx->owner = owner;
    ctx->last = last;
    ctx->pdrv = pdrv;
    ctx->fatfs = (FATFS *)fm_place_aligned(ctx->fatfs_store,
                                           sizeof(ctx->fatfs_store),
                                           sizeof(FATFS),
                                           FM_FATFS_FATFS_WIN_OFF);
    memset(ctx->fatfs, 0, sizeof(FATFS));
    for (i = 0; i < FM_MAX_OPEN_FILES; i++)
    {
        ctx->files[i] = (FIL *)fm_place_aligned(ctx->file_store[i],
                                                sizeof(ctx->file_store[i]),
                                                sizeof(FIL),
                                                FM_FATFS_FIL_WIN_OFF);
        memset(ctx->files[i], 0, sizeof(FIL));
    }
}

/* Helper for f_mkfs cross-version compatibility.
 *
 * The f_mkfs signature changed across FatFs generations and the revision
 * ID macros are not uniform:
 *   R0.14+          defines FF_DEFINED (ff.h) / FFCONF_DEF (ffconf.h) and
 *                   takes (path, const MKFS_PARM*, work, len)
 *   R0.12b..R0.13c  (STM32Cube middleware, _FFCONF/_FATFS = 68300 era)
 *                   takes (path, BYTE opt, DWORD au, work, len)
 *   R0.12a and older take (path, opt, au, work)
 *
 * Override the auto-detection with -DFM_FATFS_MKFS_VARIANT=1/2/3 if your
 * headers are unusual.  Auto-detection defaults to the 5-argument form,
 * which is what every STM32Cube FatFs middleware uses.
 */
#ifndef FM_FATFS_MKFS_VARIANT
#define FM_FATFS_MKFS_VARIANT 0 /* 0 = auto-detect */
#endif

#if FM_FATFS_MKFS_VARIANT == 3 || \
    (FM_FATFS_MKFS_VARIANT == 0 && \
     (defined(FF_DEFINED) || defined(FFCONF_DEF)))
#define FM_FATFS_MKFS_MODERN 1
#else
#define FM_FATFS_MKFS_MODERN 0
#endif

static FRESULT fatfs_do_mkfs(const char *drive, BYTE *work, UINT work_len)
{
#if FM_FATFS_MKFS_MODERN
    {                                                 /* R0.14+ */
        MKFS_PARM p;
        memset(&p, 0, sizeof(p));
#ifdef FM_ANY
        p.fmt = FM_ANY;
#endif
        return f_mkfs(drive, &p, work, work_len);
    }
#elif FM_FATFS_MKFS_VARIANT == 1
    (void)work_len;
    return f_mkfs(drive, 0, 0, work);                 /* R0.12a and older */
#else
    return f_mkfs(drive, 0, 0, work, work_len);       /* R0.12b .. R0.13c */
#endif
}

/* ------------------------------------------------------------------ */
/* Error mapping                                                       */
/* ------------------------------------------------------------------ */
static FM_Result fatfs_map_err(FRESULT fr)
{
    switch (fr)
    {
    case FR_OK:                  return FM_OK;
    case FR_DISK_ERR:            return FM_ERR_IO;
    case FR_INT_ERR:             return FM_ERR_INTERNAL;
    case FR_NOT_READY:           return FM_ERR_NOT_READY;
    case FR_NO_FILE:             return FM_ERR_NOT_FOUND;
    case FR_NO_PATH:             return FM_ERR_NOT_FOUND;
    case FR_INVALID_NAME:        return FM_ERR_INVALID_PATH;
    case FR_DENIED:              return FM_ERR_ACCESS;
    case FR_EXIST:               return FM_ERR_EXISTS;
    case FR_INVALID_OBJECT:      return FM_ERR_NOT_OPEN;
    case FR_WRITE_PROTECTED:     return FM_ERR_READ_ONLY;
    case FR_INVALID_DRIVE:       return FM_ERR_INVALID_ARGUMENT;
    case FR_NOT_ENABLED:         return FM_ERR_UNSUPPORTED;
    case FR_NO_FILESYSTEM:       return FM_ERR_CORRUPTED;
    case FR_MKFS_ABORTED:        return FM_ERR_ABORTED;
    case FR_TIMEOUT:             return FM_ERR_TIMEOUT;
    case FR_LOCKED:              return FM_ERR_BUSY;
    case FR_NOT_ENOUGH_CORE:     return FM_ERR_NO_MEMORY;
    case FR_TOO_MANY_OPEN_FILES: return FM_ERR_NO_MEMORY;
    case FR_INVALID_PARAMETER:   return FM_ERR_INVALID_ARGUMENT;
    default:                     return FM_ERR_IO;
    }
}

/* ------------------------------------------------------------------ */
/* Path helpers                                                        */
/* ------------------------------------------------------------------ */
static void fatfs_path(FatFS_Ctx *ctx, const char *path, char *out,
                       size_t out_size)
{
    size_t n = 0;

    out[0] = '\0';
    if (out_size < 4) return;

    if (ctx->pdrv >= 10)
    {
        out[n++] = (char)('0' + (ctx->pdrv / 10));
        out[n++] = (char)('0' + (ctx->pdrv % 10));
    }
    else
    {
        out[n++] = (char)('0' + ctx->pdrv);
    }
    out[n++] = ':';
    out[n++] = '/';

    while (*path == '/') path++;
    while (*path != '\0' && n + 1 < out_size)
    {
        out[n++] = *path++;
    }
    out[n] = '\0';
}

/* ------------------------------------------------------------------ */
/* Mount / format                                                      */
/* ------------------------------------------------------------------ */
/* The slot of `fs`, if it is still its own.  An unmount -- and a mount
 * that failed -- gives the slot back to the pool; the FM_FS keeps
 * pointing at it.  Mounting that FM_FS again without a new FatFS_Init()
 * (card out, card in) takes the slot back when nobody has had it since,
 * and is refused otherwise: the slot then carries the drive number of
 * somebody else, and two mounts never share one. */
static FatFS_Ctx *fatfs_claim(FM_FS *fs)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);

    if (ctx == NULL)
    {
        return NULL;
    }
    FM_Lock();
    if (ctx->owner == NULL && ctx->last == fs)
    {
        ctx->owner = fs;
    }
    else if (ctx->owner != fs)
    {
        ctx = NULL;
    }
    FM_Unlock();
    return ctx;
}

/* FS_Unmount() refuses to run while files/dirs are open, so the FIL/DIR
 * slots inside ctx are idle here.  f_mount(NULL, ...) deregisters the
 * volume but does NOT clear the FATFS object (fs_type stays set): the
 * reset is what makes the slot good for its next mount. */
static void fatfs_release(FatFS_Ctx *ctx)
{
    FM_Lock();
    ctx->owner = NULL;
    fatfs_ctx_reset(ctx);
    FM_Unlock();
}

static FM_Result fatfs_mount(FM_FS *fs, FM_Storage *storage)
{
    FatFS_Ctx *ctx = fatfs_claim(fs);
    char drive[4] = { '0', ':', 0, 0 };
    FRESULT fr;

    (void)storage;
    if (ctx == NULL)
    {
        return FM_ERR_NOT_READY;
    }
    drive[0] = (char)('0' + ctx->pdrv);
    /* Use option 0 (Lazy mount) for stable SD card mounting */
    fr = f_mount(ctx->fatfs, drive, 0);
    if (fr != FR_OK)
    {
        fatfs_release(ctx);
        return fatfs_map_err(fr);
    }
    ctx->mounted = FM_TRUE;
    return FM_OK;
}

static FM_Result fatfs_unmount(FM_FS *fs)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char drive[4] = { '0', ':', 0, 0 };

    if (ctx == NULL || ctx->owner != fs)
    {
        return FM_ERR_NOT_READY;
    }
    drive[0] = (char)('0' + ctx->pdrv);
    if (ctx->mounted)
    {
        (void)f_mount(NULL, drive, 0);
    }
    fatfs_release(ctx);
    return FM_OK;
}

static FM_Result fatfs_format(FM_FS *fs)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char drive[4] = { (char)('0' + ctx->pdrv), ':', 0, 0 };
    BYTE work[FF_MAX_SS];
    FRESULT fr;

    fr = fatfs_do_mkfs(drive, work, sizeof(work));
    return fatfs_map_err(fr);
}

static FM_Result fatfs_check(FM_FS *fs)
{
    (void)fs;
    return FM_OK;
}

/* ------------------------------------------------------------------ */
/* File operations                                                     */
/* ------------------------------------------------------------------ */
static BYTE fatfs_flags(uint32_t mode)
{
    BYTE flags = 0;

    if (mode & FM_OPEN_READ)
    {
        if (mode & FM_OPEN_WRITE) flags = FA_READ | FA_WRITE;
        else                      flags = FA_READ;
    }
    else if (mode & FM_OPEN_WRITE)
    {
        flags = FA_WRITE;
    }

    if (mode & FM_OPEN_CREATE)
    {
        if (mode & FM_OPEN_TRUNCATE) flags |= FA_CREATE_ALWAYS;
        else if (flags & FA_WRITE)   flags |= FA_OPEN_ALWAYS;
        else                         flags |= FA_OPEN_EXISTING;
    }
    else if (mode & FM_OPEN_TRUNCATE)
    {
        flags |= FA_CREATE_ALWAYS;
    }
    if (mode & FM_OPEN_APPEND)
    {
        flags |= FA_OPEN_APPEND;
    }
    return flags;
}

static FM_Result fatfs_file_open(FM_FS *fs, void *fh, const char *path, uint32_t mode)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;
#if FM_USE_THREADS
    char fpath[FM_PATH_MAX];
#else
    char *fpath = ctx->open_path;
#endif
    uint32_t i;
    FRESULT fr;

    if (fh == NULL || path == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, path, fpath, FM_PATH_MAX);

    FM_Lock();
    for (i = 0; i < FM_MAX_OPEN_FILES; i++)
    {
        if (!ctx->file_used[i]) break;
    }
    if (i == FM_MAX_OPEN_FILES)
    {
        FM_Unlock();
        return FM_ERR_NO_MEMORY;
    }
    ctx->file_used[i] = 1;
    FM_Unlock();

    fr = f_open(ctx->files[i], fpath, fatfs_flags(mode));
    if (fr != FR_OK)
    {
        FM_Lock();
        ctx->file_used[i] = 0;
        FM_Unlock();
        return fatfs_map_err(fr);
    }
    h->index = (uint16_t)i;
    h->used = 1;
    return FM_OK;
}

static FM_Result fatfs_file_close(FM_FS *fs, void *fh)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;
    uint32_t i;
    FRESULT fr;

    if (fh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    i = h->index;
    if (i >= FM_MAX_OPEN_FILES || !ctx->file_used[i]) return FM_ERR_NOT_OPEN;

    fr = f_close(ctx->files[i]);
    FM_Lock();
    ctx->file_used[i] = 0;
    FM_Unlock();
    h->used = 0;
    return fatfs_map_err(fr);
}

static FM_Result fatfs_file_read(FM_FS *fs, void *fh, void *buf, uint32_t len, uint32_t *out_read)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;
    UINT rd = 0;
    FRESULT fr;

    if (fh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    fr = f_read(ctx->files[h->index], buf, len, &rd);
    if (out_read) *out_read = (uint32_t)rd;
    if (fr != FR_OK) return fatfs_map_err(fr);
    return (rd == 0 && len != 0) ? FM_ERR_EOF : FM_OK;
}

static FM_Result fatfs_file_write(FM_FS *fs, void *fh, const void *buf, uint32_t len, uint32_t *written)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;
    UINT wr = 0;
    FRESULT fr;

    if (fh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    fr = f_write(ctx->files[h->index], buf, len, &wr);
    if (written) *written = (uint32_t)wr;
    return (fr == FR_OK) ? FM_OK : fatfs_map_err(fr);
}

static FM_Result fatfs_file_seek(FM_FS *fs, void *fh, int64_t offset, FM_SeekOrigin origin)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;
    FSIZE_t base = 0;
    FRESULT fr;

    if (fh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    if (origin == FM_SEEK_CUR) base = f_tell(ctx->files[h->index]);
    else if (origin == FM_SEEK_END) base = f_size(ctx->files[h->index]);
    else if (origin != FM_SEEK_SET) return FM_ERR_INVALID_ARGUMENT;

    if (offset < 0 && (uint64_t)(-offset) > base) return FM_ERR_INVALID_ARGUMENT;

    fr = f_lseek(ctx->files[h->index], (FSIZE_t)((int64_t)base + offset));
    return (fr == FR_OK) ? FM_OK : fatfs_map_err(fr);
}

static FM_Result fatfs_file_tell(FM_FS *fs, void *fh, uint64_t *pos)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;

    if (fh == NULL || !h->used || pos == NULL) return FM_ERR_NOT_OPEN;
    *pos = (uint64_t)f_tell(ctx->files[h->index]);
    return FM_OK;
}

static FM_Result fatfs_file_size(FM_FS *fs, void *fh, uint64_t *size)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;

    if (fh == NULL || !h->used || size == NULL) return FM_ERR_NOT_OPEN;
    *size = (uint64_t)f_size(ctx->files[h->index]);
    return FM_OK;
}

static FM_Result fatfs_file_truncate(FM_FS *fs, void *fh, uint64_t size)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;
    FRESULT fr;

    if (fh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    fr = f_lseek(ctx->files[h->index], (FSIZE_t)size);
    if (fr != FR_OK) return fatfs_map_err(fr);
    return fatfs_map_err(f_truncate(ctx->files[h->index]));
}

static FM_Result fatfs_file_flush(FM_FS *fs, void *fh)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSFileHandle *h = (FatFSFileHandle *)fh;

    if (fh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    return fatfs_map_err(f_sync(ctx->files[h->index]));
}

static FM_Result fatfs_stat(FM_FS *fs, const char *path, FM_FileInfo *info)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char fpath[FM_PATH_MAX];
    FILINFO fi;
    FRESULT fr;

    if (path == NULL || info == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, path, fpath, sizeof(fpath));
    fr = f_stat(fpath, &fi);
    if (fr != FR_OK) return fatfs_map_err(fr);

    memset(info, 0, sizeof(*info));
    (void)strncpy(info->name, fi.fname, sizeof(info->name) - 1);
    info->type = (fi.fattrib & AM_DIR) ? FM_ITEM_DIR : FM_ITEM_FILE;
    info->size = (info->type == FM_ITEM_DIR) ? 0u : (uint64_t)fi.fsize;
    if (fi.fattrib & AM_RDO) info->attributes = FM_ATTR_READ_ONLY;
    return FM_OK;
}

static FM_Result fatfs_delete(FM_FS *fs, const char *path)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char fpath[FM_PATH_MAX];

    if (path == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, path, fpath, sizeof(fpath));
    return fatfs_map_err(f_unlink(fpath));
}

static FM_Result fatfs_rename(FM_FS *fs, const char *old_path, const char *new_path)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char fold[FM_PATH_MAX];
    char fnew[FM_PATH_MAX];
    FRESULT fr;

    if (old_path == NULL || new_path == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, old_path, fold, sizeof(fold));
    fatfs_path(ctx, new_path, fnew, sizeof(fnew));

    fr = f_rename(fold, fnew);
    if (fr == FR_EXIST)
    {
        (void)f_unlink(fnew);
        fr = f_rename(fold, fnew);
    }
    return fatfs_map_err(fr);
}

static FM_Result fatfs_mkdir(FM_FS *fs, const char *path)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char fpath[FM_PATH_MAX];

    if (path == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, path, fpath, sizeof(fpath));
    return fatfs_map_err(f_mkdir(fpath));
}

static FM_Result fatfs_rmdir(FM_FS *fs, const char *path)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char fpath[FM_PATH_MAX];

    if (path == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, path, fpath, sizeof(fpath));
    return fatfs_map_err(f_rmdir(fpath));
}

static FM_Result fatfs_dir_open(FM_FS *fs, void *dh, const char *path)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSDirHandle *h = (FatFSDirHandle *)dh;
    char fpath[FM_PATH_MAX];
    uint32_t i;
    FRESULT fr;

    if (dh == NULL || path == NULL) return FM_ERR_INVALID_ARGUMENT;
    fatfs_path(ctx, path, fpath, sizeof(fpath));

    FM_Lock();
    for (i = 0; i < FM_MAX_OPEN_DIRS; i++)
    {
        if (!ctx->dir_used[i]) break;
    }
    if (i == FM_MAX_OPEN_DIRS)
    {
        FM_Unlock();
        return FM_ERR_NO_MEMORY;
    }
    ctx->dir_used[i] = 1;
    FM_Unlock();

    fr = f_opendir(&ctx->dirs[i], fpath);
    if (fr != FR_OK)
    {
        FM_Lock();
        ctx->dir_used[i] = 0;
        FM_Unlock();
        return fatfs_map_err(fr);
    }
    h->index = (uint16_t)i;
    h->used = 1;
    return FM_OK;
}

static FM_Result fatfs_dir_close(FM_FS *fs, void *dh)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSDirHandle *h = (FatFSDirHandle *)dh;
    uint32_t i;
    FRESULT fr;

    if (dh == NULL || !h->used) return FM_ERR_NOT_OPEN;
    i = h->index;
    if (i >= FM_MAX_OPEN_DIRS || !ctx->dir_used[i]) return FM_ERR_NOT_OPEN;

    fr = f_closedir(&ctx->dirs[i]);
    FM_Lock();
    ctx->dir_used[i] = 0;
    FM_Unlock();
    h->used = 0;
    return fatfs_map_err(fr);
}

static FM_Result fatfs_dir_read(FM_FS *fs, void *dh, FM_DirEntry *entry)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    FatFSDirHandle *h = (FatFSDirHandle *)dh;
    FILINFO fi;
    FRESULT fr;

    if (dh == NULL || !h->used || entry == NULL) return FM_ERR_INVALID_ARGUMENT;

    for (;;)
    {
        fr = f_readdir(&ctx->dirs[h->index], &fi);
        if (fr != FR_OK) return fatfs_map_err(fr);
        if (fi.fname[0] == '\0') return FM_ERR_EOF;

        if (strcmp(fi.fname, ".") == 0 || strcmp(fi.fname, "..") == 0) continue;

        if (strlen(fi.fname) >= sizeof(entry->name)) return FM_ERR_TOO_LARGE;

        memset(entry, 0, sizeof(*entry));
        (void)strcpy(entry->name, fi.fname);
        entry->type = (fi.fattrib & AM_DIR) ? FM_ITEM_DIR : FM_ITEM_FILE;
        entry->size = (entry->type == FM_ITEM_DIR) ? 0u : (uint64_t)fi.fsize;
        if (fi.fattrib & AM_RDO) entry->attributes = FM_ATTR_READ_ONLY;
        return FM_OK;
    }
}

static FM_Result fatfs_get_free(FM_FS *fs, uint64_t *free, uint64_t *total)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);
    char drive[4] = { (char)('0' + ctx->pdrv), ':', 0, 0 };
    DWORD clusters = 0;
    FATFS *pfs = NULL;
    FRESULT fr;

    if (free == NULL || total == NULL) return FM_ERR_INVALID_ARGUMENT;

    fr = f_getfree(drive, &clusters, &pfs);
    if (fr != FR_OK) return fatfs_map_err(fr);
    if (pfs == NULL) return FM_ERR_NOT_MOUNTED;

    *total = (uint64_t)(pfs->n_fatent - 2) * pfs->csize * FF_MAX_SS;
    *free = (uint64_t)clusters * pfs->csize * FF_MAX_SS;
    return FM_OK;
}

static FM_Result fatfs_get_type(FM_FS *fs, char *type, size_t type_size)
{
    FatFS_Ctx *ctx = fatfs_ctx(fs);

    if (type == NULL || type_size < sizeof("FAT")) return FM_ERR_INVALID_ARGUMENT;

    switch (ctx->fatfs->fs_type)
    {
    case FS_FAT12: (void)strcpy(type, "FAT12"); break;
    case FS_FAT16: (void)strcpy(type, "FAT16"); break;
    case FS_FAT32: (void)strcpy(type, "FAT32"); break;
    case FS_EXFAT: (void)strcpy(type, "exFAT"); break;
    default:       (void)strcpy(type, "FAT");   break;
    }
    return FM_OK;
}

/* ------------------------------------------------------------------ */
/* Public API                                                          */
/* ------------------------------------------------------------------ */
FM_Result FatFS_Init(FM_FS *fs, uint8_t pdrv)
{
    FatFS_Ctx *ctx = NULL;
    uint32_t i;

    if (fs == NULL) return FM_ERR_INVALID_ARGUMENT;
    if (pdrv >= 10 || pdrv >= FF_VOLUMES) return FM_ERR_INVALID_ARGUMENT;

    memset(fs, 0, sizeof(*fs));

    FM_Lock();
    /* An FM_FS that is initialised again keeps the slot it has; one that
     * had a slot before gets that one back if it is free.  A slot is
     * taken from FatFS_Init() on, not from the first disk access on:
     * two FM_FS initialised before either is mounted (SD on drive 0,
     * USB on drive 1) used to end up in the same slot, both on the
     * drive of the second. */
    for (i = 0; i < FM_MAX_FS; i++)
    {
        if (g_fatfs[i].owner == fs)
        {
            ctx = &g_fatfs[i];
            break;
        }
    }
    for (i = 0; ctx == NULL && i < FM_MAX_FS; i++)
    {
        if (g_fatfs[i].owner == NULL && g_fatfs[i].last == fs)
        {
            ctx = &g_fatfs[i];
        }
    }
    /* ...then one nobody is waiting for, then any free one */
    for (i = 0; ctx == NULL && i < FM_MAX_FS; i++)
    {
        if (g_fatfs[i].owner == NULL && g_fatfs[i].last == NULL)
        {
            ctx = &g_fatfs[i];
        }
    }
    for (i = 0; ctx == NULL && i < FM_MAX_FS; i++)
    {
        if (g_fatfs[i].owner == NULL)
        {
            ctx = &g_fatfs[i];
        }
    }
    if (ctx != NULL)
    {
        ctx->owner = fs;
        ctx->last = fs;
        ctx->pdrv = pdrv;
        fatfs_ctx_reset(ctx);
    }
    FM_Unlock();

    if (ctx == NULL) return FM_ERR_NO_MEMORY;
    (void)strncpy(fs->name, "FATFS", sizeof(fs->name) - 1);
    fs->user = ctx;
    fs->ops.mount = fatfs_mount;
    fs->ops.unmount = fatfs_unmount;
    fs->ops.format = fatfs_format;
    fs->ops.check = fatfs_check;
    fs->ops.file_open = fatfs_file_open;
    fs->ops.file_close = fatfs_file_close;
    fs->ops.file_read = fatfs_file_read;
    fs->ops.file_write = fatfs_file_write;
    fs->ops.file_seek = fatfs_file_seek;
    fs->ops.file_tell = fatfs_file_tell;
    fs->ops.file_size = fatfs_file_size;
    fs->ops.file_truncate = fatfs_file_truncate;
    fs->ops.file_flush = fatfs_file_flush;
    fs->ops.stat = fatfs_stat;
    fs->ops.delete_file = fatfs_delete;
    fs->ops.rename = fatfs_rename;
    fs->ops.mkdir = fatfs_mkdir;
    fs->ops.rmdir = fatfs_rmdir;
    fs->ops.dir_open = fatfs_dir_open;
    fs->ops.dir_close = fatfs_dir_close;
    fs->ops.dir_read = fatfs_dir_read;
    fs->ops.get_free = fatfs_get_free;
    fs->ops.get_type = fatfs_get_type;
    return FM_OK;
}

FM_Result FatFS_BindStorage(uint8_t pdrv, FM_Storage *storage)
{
#if FM_FATFS_PROVIDE_DISKIO
    if (pdrv >= FF_VOLUMES) return FM_ERR_INVALID_ARGUMENT;
    g_fatfs_storage[pdrv] = storage;
    return FM_OK;
#else
    (void)pdrv;
    (void)storage;
    return FM_ERR_UNSUPPORTED;
#endif
}

FM_Result FatFS_MountDefault(FM_FS *fs, uint8_t pdrv, FM_Storage *storage)
{
    FM_Result r = FatFS_Init(fs, pdrv);
    if (r != FM_OK) return r;

    r = FatFS_BindStorage(pdrv, storage);
    if (r != FM_OK)
    {
        /* not going to be mounted: do not keep a slot for it */
        fatfs_release(fatfs_ctx(fs));
        return r;
    }

    return FS_MountDefault(fs);
}

/* ------------------------------------------------------------------ */
/* FatFS diskio bridge (disabled with FM_FATFS_PROVIDE_DISKIO=0)       */
/* ------------------------------------------------------------------ */
#if FM_FATFS_PROVIDE_DISKIO

static FM_Storage *fatfs_storage_for(BYTE pdrv)
{
    if (pdrv >= FF_VOLUMES) return NULL;
    return g_fatfs_storage[pdrv];
}

static WORD fatfs_sector_size(FM_Storage *s)
{
    return (s != NULL && s->block_size != 0 && s->block_size <= 65535u)
               ? (WORD)s->block_size : 512u;
}

DSTATUS disk_initialize(BYTE pdrv)
{
    FM_Storage *s = fatfs_storage_for(pdrv);
    if (s == NULL || !FM_Storage_IsPresent(s)) return STA_NOINIT;
    return 0;
}

DSTATUS disk_status(BYTE pdrv)
{
    FM_Storage *s = fatfs_storage_for(pdrv);
    if (s == NULL || !FM_Storage_IsPresent(s)) return STA_NOINIT;
    if (s->read_only) return STA_PROTECT;
    return 0;
}

DRESULT disk_read(BYTE pdrv, BYTE *buff, LBA_t sector, UINT count)
{
    FM_Storage *s = fatfs_storage_for(pdrv);
    WORD ss;
    uint32_t bytes;

    if (s == NULL || s->read == NULL || buff == NULL) return RES_PARERR;
    ss = fatfs_sector_size(s);
    bytes = (uint32_t)count * ss;
    if (!FM_Cache_SdDirectOk(buff, bytes) && ss == 512u)
    {
        UINT i;

        for (i = 0; i < count; i++)
        {
            if (s->read(s, (uint64_t)(sector + i) * ss, fm_sd_bounce, ss) != FM_OK)
            {
                return RES_ERROR;
            }
            FM_Cache_InvalidateAfterDma(fm_sd_bounce, ss);
            memcpy(buff + (size_t)i * ss, fm_sd_bounce, ss);
        }
        return RES_OK;
    }
    if (s->read(s, (uint64_t)sector * ss, buff, bytes) != FM_OK)
    {
        return RES_ERROR;
    }
    FM_Cache_InvalidateAfterDma(buff, bytes);
    return RES_OK;
}

DRESULT disk_write(BYTE pdrv, const BYTE *buff, LBA_t sector, UINT count)
{
    FM_Storage *s = fatfs_storage_for(pdrv);
    WORD ss;
    uint32_t bytes;

    if (s == NULL || s->write == NULL || buff == NULL) return RES_PARERR;
    if (s->read_only) return RES_WRPRT;
    ss = fatfs_sector_size(s);
    bytes = (uint32_t)count * ss;
    if (!FM_Cache_SdDirectOk(buff, bytes) && ss == 512u)
    {
        UINT i;

        for (i = 0; i < count; i++)
        {
            memcpy(fm_sd_bounce, buff + (size_t)i * ss, ss);
            FM_Cache_CleanForDma(fm_sd_bounce, ss);
            if (s->write(s, (uint64_t)(sector + i) * ss, fm_sd_bounce, ss) != FM_OK)
            {
                return RES_ERROR;
            }
        }
        return RES_OK;
    }
    FM_Cache_CleanForDma(buff, bytes);
    return (s->write(s, (uint64_t)sector * ss, buff, bytes) == FM_OK)
               ? RES_OK : RES_ERROR;
}

DRESULT disk_ioctl(BYTE pdrv, BYTE cmd, void *buff)
{
    FM_Storage *s = fatfs_storage_for(pdrv);
    WORD ss;

    if (s == NULL) return RES_PARERR;
    ss = fatfs_sector_size(s);
    switch (cmd)
    {
    case CTRL_SYNC:
        if (s->sync != NULL) return (s->sync(s) == FM_OK) ? RES_OK : RES_ERROR;
        return RES_OK;
    case GET_SECTOR_COUNT:
        *(LBA_t *)buff = (LBA_t)(s->capacity / ss);
        return RES_OK;
    case GET_SECTOR_SIZE:
        *(WORD *)buff = ss;
        return RES_OK;
    case GET_BLOCK_SIZE:
        /* FatFS expects erase-block size in logical sectors, not bytes. */
        *(DWORD *)buff = (s->erase_size >= ss && s->erase_size % ss == 0)
                            ? (DWORD)(s->erase_size / ss) : 1u;
        return RES_OK;
    case CTRL_TRIM:
        if (s->erase != NULL)
        {
            LBA_t *range = (LBA_t *)buff;
            return (s->erase(s, (uint64_t)range[0] * ss, (uint32_t)(range[1] - range[0] + 1) * ss) == FM_OK) ? RES_OK : RES_ERROR;
        }
        return RES_OK;
    default:
        return RES_PARERR;
    }
}

#endif /* FM_FATFS_PROVIDE_DISKIO */

#endif /* FM_USE_FATFS */
